<script setup lang="ts">
import { ref, computed, onMounted, onBeforeUnmount } from 'vue';
import Pagination from './Pagination.vue'; import Skeleton from './Skeleton.vue'; import Empty from './Empty.vue';
import './styles/theme.css'; import './styles/list.css';
interface PaginationConfig { pageSize?: number; current?: number; defaultCurrent?: number; onChange?: (page: number, size: number) => void; position?: 'top' | 'bottom' | 'both'; align?: 'start' | 'center' | 'end'; showSizeChanger?: boolean; pageSizeOptions?: number[] }
const props = withDefaults(defineProps<{ dataSource: unknown[]; rowKey?: string | ((item: unknown, index: number) => string | number); header?: string; footer?: string; bordered?: boolean; split?: boolean; size?: 'sm' | 'md' | 'lg'; loading?: boolean; loadingRows?: number; emptyText?: string; grid?: { column?: number; gutter?: number; xs?: number; sm?: number; md?: number; lg?: number }; pagination?: boolean | PaginationConfig; height?: number }>(), { split: true, size: 'md', loadingRows: 3, emptyText: '暂无数据' });
const emit = defineEmits<{ endReached: []; pageChange: [page: number, size: number] }>(); const root = ref<HTMLElement | null>(null); const width = ref(0); let observer: ResizeObserver | undefined;
onMounted(() => { if (typeof ResizeObserver === 'undefined') return; observer = new ResizeObserver(([entry]) => { width.value = entry.contentRect.width; }); if (root.value) observer.observe(root.value); }); onBeforeUnmount(() => observer?.disconnect());
const config = computed(() => props.pagination ? props.pagination === true ? {} : props.pagination : null); const inner = ref(config.value?.defaultCurrent ?? 1); const activeSize = ref(config.value?.pageSize ?? 10); const page = computed(() => config.value?.current ?? inner.value); const items = computed(() => config.value ? props.dataSource.slice((page.value - 1) * activeSize.value, page.value * activeSize.value) : props.dataSource); const columns = computed(() => { const grid = props.grid; if (!grid) return 1; if (!width.value) return grid.column ?? 1; return width.value < 576 ? grid.xs ?? grid.column ?? 1 : width.value < 768 ? grid.sm ?? grid.xs ?? grid.column ?? 1 : width.value < 992 ? grid.md ?? grid.sm ?? grid.xs ?? grid.column ?? 1 : grid.lg ?? grid.md ?? grid.sm ?? grid.xs ?? grid.column ?? 1; });
function key(item: unknown, index: number) { if (typeof props.rowKey === 'function') return props.rowKey(item, index); if (props.rowKey && item && typeof item === 'object') return String((item as Record<string, unknown>)[props.rowKey]); return index; }
function change(page: number, count: number) { if (config.value?.current === undefined) inner.value = page; activeSize.value = count; config.value?.onChange?.(page, count); emit('pageChange', page, count); }
function scroll(event: Event) { const target = event.currentTarget as HTMLElement; if (target.scrollTop + target.clientHeight >= target.scrollHeight - 24) emit('endReached'); }
</script>
<template><div ref="root" :class="['at-list', `at-list--${size}`, { 'at-list--bordered': bordered, 'at-list--split': split && !grid, 'at-list--grid': grid }]"><div v-if="header || $slots.header" class="at-list__header"><slot name="header">{{ header }}</slot></div><div v-if="config && dataSource.length && (config.position === 'top' || config.position === 'both')" :class="['at-list__pagination', `at-list__pagination--${config.align ?? 'end'}`]"><Pagination :current="page" :page-size="activeSize" :total="dataSource.length" :show-size-changer="config.showSizeChanger" :page-size-options="config.pageSizeOptions" @change="change" /></div><div class="at-list__body" :style="height ? { maxHeight: `${height}px`, overflowY: 'auto' } : undefined" @scroll="scroll"><div v-if="loading" class="at-list__skeletons" aria-busy="true" aria-label="加载中"><div v-for="index in loadingRows" :key="index" class="at-list__item"><Skeleton active avatar title :paragraph="{ rows: 1 }" /></div></div><div v-else-if="!items.length" class="at-list__empty"><Empty :description="emptyText" /></div><ul v-else :class="['at-list__items', { 'at-list__items--grid': grid }]" :style="grid ? { gridTemplateColumns: `repeat(${columns}, minmax(0, 1fr))`, gap: `${grid.gutter ?? 16}px` } : undefined"><li v-for="(item, index) in items" :key="key(item, index)" class="at-list__cell"><slot :item="item" :index="index">{{ item }}</slot></li></ul></div><div v-if="config && dataSource.length && (!config.position || config.position === 'bottom' || config.position === 'both')" :class="['at-list__pagination', `at-list__pagination--${config.align ?? 'end'}`]"><Pagination :current="page" :page-size="activeSize" :total="dataSource.length" :show-size-changer="config.showSizeChanger" :page-size-options="config.pageSizeOptions" @change="change" /></div><div v-if="footer || $slots.footer" class="at-list__footer"><slot name="footer">{{ footer }}</slot></div></div></template>
